+const dialog = document.querySelector(".confirm-dialog");
+const openButton = document.querySelector(".trigger");
+const closeButton = document.querySelector("[data-close-dialog]");
+const confirmButton = document.querySelector("[data-confirm-delete]");
+const statusMessage = document.querySelector("#status-message");
+
+openButton.addEventListener("click", () => {
+  dialog.showModal();
+});
+
+closeButton.addEventListener("click", () => {
+  dialog.close();
+});
+
+confirmButton.addEventListener("click", () => {
+  dialog.close();
+  statusMessage.textContent = "Image deleted from your library.";
+  openButton.textContent = "Image deleted";
+  openButton.disabled = true;
+});
+
+dialog.addEventListener("click", (event) => {
+  const dialogBounds = dialog.getBoundingClientRect();
+  const clickedBackdrop =
+    event.clientX < dialogBounds.left ||
+    event.clientX > dialogBounds.right ||
+    event.clientY < dialogBounds.top ||
+    event.clientY > dialogBounds.bottom;
+
+  if (clickedBackdrop) {
+    dialog.close();
+  }
+});
